<script setup lang="ts">
/**
 * The application frame (`design/archetypes/app-shell.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/app-shell.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  computed,
  onBeforeUnmount,
  onMounted,
  provide,
  ref,
  useTemplateRef,
  watch,
  type VNode,
} from 'vue'

import {
  PageTransition,
  agentMember,
  currentRailDestination,
  goToRailDestination,
  railDestinations,
} from '@polymorph/vue'
import styles from '@polymorph/recipes/archetypes/app-shell.module.css'
import transitions from '@polymorph/recipes/conventions/page-transitions.module.css'
import Button from '../controls/Button.vue'
import type { AppShellNavGroupProps } from './AppShellNavGroup.vue'
import type { AppShellNavItemProps } from './AppShellNavItem.vue'
import type { AppShellUserCardProps } from './AppShellUserCard.vue'

export type NavItemProps = AppShellNavItemProps

export type NavGroupProps = AppShellNavGroupProps

export type UserCardProps = AppShellUserCardProps

export interface AppShellTopbar {
  leading?: VNode
  trailing?: VNode
}

export interface AppShellProps {
  collapsed?: boolean
  /**
   * A bounded, responsive reading surface for pages composed directly from controls.
   */
  contentLayout?: 'full' | 'page'
  defaultCollapsed?: boolean
  /**
   * Application-localized navigation names.
   */
  messages?: {
    primaryNavigation: string
    expandSidebar: string
    collapseSidebar: string
    closeNavigation: string
    openNavigation: string
    skipToContent?: string
  }
  /**
   * Where the navigation is drawn at frame widths. `'rail'` is the column at the frame's start.
   * `'top'` lays the same navigation along the frame's top row, before the topbar's slots, and
   * the rail's width collapse does not apply. Below the drawer breakpoint both are the same
   * drawer.
   */
  navigation?: 'top' | 'rail'
  pending?: boolean
  topbar?: AppShellTopbar
  /**
   * Presentation identity for page arrivals; does not key or remount children. A new key also
   * closes the small-viewport drawer.
   */
  transitionKey?: string
}

defineOptions({ name: 'AppShell', inheritAttrs: false })

const props = withDefaults(defineProps<AppShellProps>(), {
  collapsed: undefined,
  contentLayout: 'full',
  defaultCollapsed: undefined,
  navigation: 'rail',
  pending: false,
})
const emit = defineEmits<{ collapsedChange: [collapsed: boolean] }>()
defineSlots<{
  banner?: (props: Record<string, never>) => unknown
  brand?: (props: Record<string, never>) => unknown
  default: (props: Record<string, never>) => unknown
  dock?: (props: Record<string, never>) => unknown
  sidebar: (props: Record<string, never>) => unknown
  sidebarFooter?: (props: Record<string, never>) => unknown
}>()
const uncontrolled = ref(props.defaultCollapsed ?? false)
const drawer = ref(false)
const drawerToggle = useTemplateRef<HTMLElement>('drawerToggle')
const rail = useTemplateRef<HTMLElement>('rail')
const railToggle = useTemplateRef<HTMLElement>('railToggle')
const held = computed(() => props.collapsed ?? uncontrolled.value)
const isCollapsed = computed(() => props.navigation === 'rail' && held.value)
const say = computed(
  () =>
    props.messages ?? {
      primaryNavigation: 'Primary',
      expandSidebar: 'Expand sidebar',
      collapseSidebar: 'Collapse sidebar',
      closeNavigation: 'Close navigation',
      openNavigation: 'Open navigation',
    },
)
const toggle = computed(() => (): void => {
  const next = !held.value
  uncontrolled.value = next
  emit('collapsedChange', next)
})
provide('polymorph:AppShell', {
  get collapsed() {
    return isCollapsed.value
  },
})
const effect1 = () => {
  drawer.value
    ? rail.value?.focus()
    : drawerToggle.value?.querySelector<HTMLElement>('button')?.focus()
}
watch(() => drawer.value, effect1, { flush: 'post' })
const effect2 = () => {
  drawer.value = false
}
watch(() => props.transitionKey, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'AppShell',
    element: () => rail.value,
    state: () => ({
      collapsed: isCollapsed.value,
      open: drawer.value,
      destinations: railDestinations(rail.value, { item: styles.navItem, label: styles.navLabel }),
      current: currentRailDestination(rail.value, { item: styles.navItem, label: styles.navLabel }),
    }),
    actions: {
      collapse: () =>
        (() => {
          if (!railToggle.value || window.getComputedStyle(railToggle.value).display === 'none')
            throw new Error(
              'The rail has no width to change here: below the breakpoint it is a drawer, and with the navigation on top there is no rail.',
            )
          if (!held.value) toggle.value()
        })(),
      expand: () =>
        (() => {
          if (!railToggle.value || window.getComputedStyle(railToggle.value).display === 'none')
            throw new Error(
              'The rail has no width to change here: below the breakpoint it is a drawer, and with the navigation on top there is no rail.',
            )
          if (held.value) toggle.value()
        })(),
      open: () =>
        (() => {
          if (!drawerToggle.value || window.getComputedStyle(drawerToggle.value).display === 'none')
            throw new Error(
              'There is no drawer here: above the breakpoint the navigation is drawn beside the page or along its top.',
            )
          drawer.value = true
        })(),
      close: () =>
        (() => {
          if (!drawerToggle.value || window.getComputedStyle(drawerToggle.value).display === 'none')
            throw new Error(
              'There is no drawer here: above the breakpoint the navigation is drawn beside the page or along its top.',
            )
          drawer.value = false
        })(),
      go: {
        argument: 'id',
        run: (value) =>
          goToRailDestination(rail.value, { item: styles.navItem, label: styles.navLabel }, value),
      },
    },
    withholds: () => [railToggle.value, drawerToggle.value],
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <div
    :class="styles.shell"
    :data-collapsed="isCollapsed ? '' : undefined"
    :data-navigation="navigation === 'top' ? 'top' : undefined"
    :data-drawer="drawer ? '' : undefined"
    data-member="app-shell"
  >
    <!-- skip -->
    <a :class="styles.skip" href="#content">
      {{ say.skipToContent ?? 'Skip to content' }}
    </a>
    <!-- banner -->
    <div v-if="$slots.banner" :class="styles.banner">
      <slot name="banner" />
    </div>
    <!-- sidebar -->
    <nav ref="rail" :class="styles.sidebar" :aria-label="say.primaryNavigation" tabindex="-1">
      <!-- railHead -->
      <div :class="styles.railHead">
        <!-- brand -->
        <div v-if="$slots.brand" :class="styles.brand">
          <slot name="brand" />
        </div>
        <!-- toggle -->
        <div ref="railToggle" :class="styles.toggle">
          <Button
            variant="ghost"
            tone="neutral"
            size="sm"
            :iconOnly="true"
            :icon="isCollapsed ? 'next' : 'previous'"
            :label="isCollapsed ? say.expandSidebar : say.collapseSidebar"
            @click="toggle()"
          />
        </div>
      </div>
      <!-- nav -->
      <div :class="styles.nav">
        <slot name="sidebar" />
      </div>
      <!-- sidebarFooter -->
      <div v-if="$slots.sidebarFooter" :class="styles.sidebarFooter">
        <slot name="sidebarFooter" />
      </div>
    </nav>
    <!-- topbar -->
    <header :class="styles.topbar">
      <!-- leading -->
      <div :class="styles.topbarSlot">
        <!-- drawerToggle -->
        <span ref="drawerToggle" :class="styles.drawerToggle">
          <Button
            variant="ghost"
            tone="neutral"
            size="sm"
            :iconOnly="true"
            icon="menu"
            :label="drawer ? say.closeNavigation : say.openNavigation"
            @click="drawer = !drawer"
          />
        </span>
        <template v-if="topbar?.leading !== undefined">
          <component :is="topbar?.leading" />
        </template>
      </div>
      <!-- trailing -->
      <div :class="styles.topbarSlot">
        <template v-if="topbar?.trailing !== undefined">
          <component :is="topbar?.trailing" />
        </template>
      </div>
    </header>
    <!-- scrim -->
    <button
      v-if="drawer"
      :class="styles.scrim"
      type="button"
      :aria-label="say.closeNavigation"
      @click="drawer = false"
    />
    <!-- content -->
    <component
      :is="PageTransition"
      :class="[styles.content, transitionKey !== undefined ? transitions.page : undefined]"
      as="main"
      id="content"
      :transitionKey="transitionKey"
      :pending="pending"
      :ribbon="transitions.indicator"
    >
      <!-- page -->
      <div v-if="contentLayout === 'page'" :class="styles.page">
        <slot />
      </div>
      <template v-else>
        <slot />
      </template>
    </component>
    <!-- dock -->
    <div v-if="$slots.dock" :class="styles.dock">
      <slot name="dock" />
    </div>
  </div>
</template>
